{
  "subtype": "predictive_feature_engineering",
  "focus_variable": "visit_duration_min",
  "per_column": [
    {
      "name": "visit_type",
      "role": "predictor",
      "is_predictor": true,
      "rationale": "Category of visit is knowable independent of duration and plausibly correlates with how long a visit runs; a legitimate upstream predictor."
    },
    {
      "name": "clinical_severity_level",
      "role": "predictor",
      "is_predictor": true,
      "rationale": "Severity is a clinical characteristic of the case that is not a component of duration and could drive longer visits; valid predictor."
    },
    {
      "name": "new_diagnosis_flag",
      "role": "predictor",
      "is_predictor": true,
      "rationale": "Whether a new diagnosis was made is a case attribute that plausibly extends visit time without being a restatement of duration."
    },
    {
      "name": "chronic_disease_count",
      "role": "predictor",
      "is_predictor": true,
      "rationale": "Patient comorbidity burden is an independent characteristic that can lengthen visits; legitimate predictor."
    },
    {
      "name": "diagnostic_test_ordered",
      "role": "predictor",
      "is_predictor": true,
      "rationale": "Ordering tests is a within-visit activity co-occurring with duration; borderline for potential co-determination, but it is not a deterministic function of duration and carries genuine predictive signal, so accepted as predictor."
    },
    {
      "name": "new_medication_initiated",
      "role": "predictor",
      "is_predictor": true,
      "rationale": "Medication changes reflect visit complexity and plausibly add time; not a restatement of duration, so a valid predictor."
    },
    {
      "name": "specialist_consult_triggered",
      "role": "predictor",
      "is_predictor": true,
      "rationale": "Triggering a consult signals complexity/added activity that lengthens a visit; independent of the duration value itself."
    },
    {
      "name": "counseling_topic",
      "role": "predictor",
      "is_predictor": true,
      "rationale": "Presence and type of counseling is an activity indicator plausibly associated with longer visits and not a direct component of duration."
    },
    {
      "name": "outbound_referral_count",
      "role": "predictor",
      "is_predictor": true,
      "rationale": "Number of referrals reflects visit complexity and is not a restatement or deterministic function of duration; carries predictive signal."
    }
  ],
  "n_predictors": 9,
  "predictive_utility": 0.8,
  "rationale": "All added columns are case/activity characteristics that lie outside the duration variable itself, none restate or deterministically encode minutes, and none are post-outcome leakage. As a set they capture visit complexity, severity, comorbidity, and in-visit actions -- strong, diverse predictive leverage. Some columns (tests ordered, referrals, consults) are contemporaneous activities that partly co-determine duration and mildly overlap, so utility is high but not maximal."
}

